        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.CreateRenderer"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.RenderClear"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.RenderFillRect"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.RenderFillRects"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.RenderLine"/>
