        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.RenderPoint"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.RenderPoints"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.RenderRect"/>
