        ///   SDL_GetError() for more information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     The following read-only properties are provided by SDL:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_TEXTURE_COLORSPACE_NUMBER</c>: an SDL_Colorspace value describing
        ///     the texture colorspace.
        ///     - <c>SDL_PROP_TEXTURE_FORMAT_NUMBER</c>: one of the enumerated values in
        ///     SDL_PixelFormat.
        ///     - <c>SDL_PROP_TEXTURE_ACCESS_NUMBER</c>: one of the enumerated values in
        ///     SDL_TextureAccess.
        ///     - <c>SDL_PROP_TEXTURE_WIDTH_NUMBER</c>: the width of the texture in pixels.
        ///     - <c>SDL_PROP_TEXTURE_HEIGHT_NUMBER</c>: the height of the texture in pixels.
        ///     - <c>SDL_PROP_TEXTURE_SDR_WHITE_POINT_FLOAT</c>: for HDR10 and floating point
        ///     textures, this defines the value of 100% diffuse white, with higher
        ///     values being displayed in the High Dynamic Range headroom. This defaults
        ///     to 100 for HDR10 textures and 1.0 for other textures.
        ///     - <c>SDL_PROP_TEXTURE_HDR_HEADROOM_FLOAT</c>: for HDR10 and floating point
        ///     textures, this defines the maximum dynamic range used by the content, in
        ///     terms of the SDR white point. If this is defined, any values outside the
        ///     range supported by the display will be scaled into the available HDR
        ///     headroom, otherwise they are clipped. This defaults to 1.0 for SDR
        ///     textures, 4.0 for HDR10 textures, and no default for floating point
        ///     textures.
        ///   </para>
        ///   <para>
        ///     With the direct3d11 renderer:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_TEXTURE_D3D11_TEXTURE_POINTER</c>: the ID3D11Texture2D associated
        ///     with the texture
        ///     - <c>SDL_PROP_TEXTURE_D3D11_TEXTURE_U_POINTER</c>: the ID3D11Texture2D
        ///     associated with the U plane of a YUV texture
        ///     - <c>SDL_PROP_TEXTURE_D3D11_TEXTURE_V_POINTER</c>: the ID3D11Texture2D
        ///     associated with the V plane of a YUV texture
        ///   </para>
        ///   <para>
        ///     With the direct3d12 renderer:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_TEXTURE_D3D12_TEXTURE_POINTER</c>: the ID3D12Resource associated
        ///     with the texture
        ///     - <c>SDL_PROP_TEXTURE_D3D12_TEXTURE_U_POINTER</c>: the ID3D12Resource associated
        ///     with the U plane of a YUV texture
        ///     - <c>SDL_PROP_TEXTURE_D3D12_TEXTURE_V_POINTER</c>: the ID3D12Resource associated
        ///     with the V plane of a YUV texture
        ///   </para>
        ///   <para>
        ///     With the vulkan renderer:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_TEXTURE_VULKAN_TEXTURE_NUMBER</c>: the VkImage associated with the
        ///     texture
        ///   </para>
        ///   <para>
        ///     With the opengl renderer:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_TEXTURE_OPENGL_TEXTURE_NUMBER</c>: the GLuint texture associated
        ///     with the texture
        ///     - <c>SDL_PROP_TEXTURE_OPENGL_TEXTURE_UV_NUMBER</c>: the GLuint texture
        ///     associated with the UV plane of an NV12 texture
        ///     - <c>SDL_PROP_TEXTURE_OPENGL_TEXTURE_U_NUMBER</c>: the GLuint texture associated
        ///     with the U plane of a YUV texture
        ///     - <c>SDL_PROP_TEXTURE_OPENGL_TEXTURE_V_NUMBER</c>: the GLuint texture associated
        ///     with the V plane of a YUV texture
        ///     - <c>SDL_PROP_TEXTURE_OPENGL_TEXTURE_TARGET_NUMBER</c>: the GLenum for the
        ///     texture target (<c>GL_TEXTURE_2D</c>, <c>GL_TEXTURE_RECTANGLE_ARB</c>, etc)
        ///     - <c>SDL_PROP_TEXTURE_OPENGL_TEX_W_FLOAT</c>: the texture coordinate width of
        ///     the texture (0.0 - 1.0)
        ///     - <c>SDL_PROP_TEXTURE_OPENGL_TEX_H_FLOAT</c>: the texture coordinate height of
        ///     the texture (0.0 - 1.0)
        ///   </para>
        ///   <para>
        ///     With the opengles2 renderer:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_TEXTURE_OPENGLES2_TEXTURE_NUMBER</c>: the GLuint texture
        ///     associated with the texture
        ///     - <c>SDL_PROP_TEXTURE_OPENGLES2_TEXTURE_UV_NUMBER</c>: the GLuint texture
        ///     associated with the UV plane of an NV12 texture
        ///     - <c>SDL_PROP_TEXTURE_OPENGLES2_TEXTURE_U_NUMBER</c>: the GLuint texture
        ///     associated with the U plane of a YUV texture
        ///     - <c>SDL_PROP_TEXTURE_OPENGLES2_TEXTURE_V_NUMBER</c>: the GLuint texture
        ///     associated with the V plane of a YUV texture
        ///     - <c>SDL_PROP_TEXTURE_OPENGLES2_TEXTURE_TARGET_NUMBER</c>: the GLenum for the
        ///     texture target (<c>GL_TEXTURE_2D</c>, <c>GL_TEXTURE_EXTERNAL_OES</c>, etc)
        ///   </para>
        ///   <para>
        ///     With the gpu renderer:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_TEXTURE_GPU_TEXTURE_POINTER</c>: the SDL_GPUTexture associated
        ///     with the texture
        ///     - <c>SDL_PROP_TEXTURE_GPU_TEXTURE_UV_POINTER</c>: the SDL_GPUTexture associated
        ///     with the UV plane of an NV12 texture
        ///     - <c>SDL_PROP_TEXTURE_GPU_TEXTURE_U_POINTER</c>: the SDL_GPUTexture associated
        ///     with the U plane of a YUV texture
        ///     - <c>SDL_PROP_TEXTURE_GPU_TEXTURE_V_POINTER</c>: the SDL_GPUTexture associated
        ///     with the V plane of a YUV texture
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   It is safe to call this function from any thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        public uint GetProperties() => Sdl.Render.GetTextureProperties(this);

