        /// <summary>
        ///   Get the properties associated with a window.
        /// </summary>
        /// <returns>
        ///   a valid property ID on success or 0 on failure; call
        ///   SDL_GetError() for more information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     The following read-only properties are provided by SDL:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_WINDOW_SHAPE_POINTER</c>: the surface associated with a shaped
        ///     window
        ///     - <c>SDL_PROP_WINDOW_HDR_ENABLED_BOOLEAN</c>: true if the window has HDR
        ///     headroom above the SDR white point. This property can change dynamically
        ///     when SDL_EVENT_WINDOW_HDR_STATE_CHANGED is sent.
        ///     - <c>SDL_PROP_WINDOW_SDR_WHITE_LEVEL_FLOAT</c>: the value of SDR white in the
        ///     SDL_COLORSPACE_SRGB_LINEAR colorspace. On Windows this corresponds to the
        ///     SDR white level in scRGB colorspace, and on Apple platforms this is
        ///     always 1.0 for EDR content. This property can change dynamically when
        ///     SDL_EVENT_WINDOW_HDR_STATE_CHANGED is sent.
        ///     - <c>SDL_PROP_WINDOW_HDR_HEADROOM_FLOAT</c>: the additional high dynamic range
        ///     that can be displayed, in terms of the SDR white point. When HDR is not
        ///     enabled, this will be 1.0. This property can change dynamically when
        ///     SDL_EVENT_WINDOW_HDR_STATE_CHANGED is sent.
        ///   </para>
        ///   <para>
        ///     On Android:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_WINDOW_ANDROID_WINDOW_POINTER</c>: the ANativeWindow associated
        ///     with the window
        ///     - <c>SDL_PROP_WINDOW_ANDROID_SURFACE_POINTER</c>: the EGLSurface associated with
        ///     the window
        ///   </para>
        ///   <para>
        ///     On iOS:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_WINDOW_UIKIT_WINDOW_POINTER</c>: the <c>(__unsafe_unretained)</c>
        ///     UIWindow associated with the window
        ///     - <c>SDL_PROP_WINDOW_UIKIT_METAL_VIEW_TAG_NUMBER</c>: the NSInteger tag
        ///     associated with metal views on the window
        ///     - <c>SDL_PROP_WINDOW_UIKIT_OPENGL_FRAMEBUFFER_NUMBER</c>: the OpenGL view's
        ///     framebuffer object. It must be bound when rendering to the screen using
        ///     OpenGL.
        ///     - <c>SDL_PROP_WINDOW_UIKIT_OPENGL_RENDERBUFFER_NUMBER</c>: the OpenGL view's
        ///     renderbuffer object. It must be bound when SDL_GL_SwapWindow is called.
        ///     - <c>SDL_PROP_WINDOW_UIKIT_OPENGL_RESOLVE_FRAMEBUFFER_NUMBER</c>: the OpenGL
        ///     view's resolve framebuffer, when MSAA is used.
        ///   </para>
        ///   <para>
        ///     On KMS/DRM:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_WINDOW_KMSDRM_DEVICE_INDEX_NUMBER</c>: the device index associated
        ///     with the window (e.g. the X in /dev/dri/cardX)
        ///     - <c>SDL_PROP_WINDOW_KMSDRM_DRM_FD_NUMBER</c>: the DRM FD associated with the
        ///     window
        ///     - <c>SDL_PROP_WINDOW_KMSDRM_GBM_DEVICE_POINTER</c>: the GBM device associated
        ///     with the window
        ///   </para>
        ///   <para>
        ///     On macOS:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_WINDOW_COCOA_WINDOW_POINTER</c>: the <c>(__unsafe_unretained)</c>
        ///     NSWindow associated with the window
        ///     - <c>SDL_PROP_WINDOW_COCOA_METAL_VIEW_TAG_NUMBER</c>: the NSInteger tag
        ///     associated with metal views on the window
        ///   </para>
        ///   <para>
        ///     On OpenVR:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_WINDOW_OPENVR_OVERLAY_ID_NUMBER</c>: the OpenVR Overlay Handle ID
        ///     for the associated overlay window.
        ///   </para>
        ///   <para>
        ///     On Vivante:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_WINDOW_VIVANTE_DISPLAY_POINTER</c>: the EGLNativeDisplayType
        ///     associated with the window
        ///     - <c>SDL_PROP_WINDOW_VIVANTE_WINDOW_POINTER</c>: the EGLNativeWindowType
        ///     associated with the window
        ///     - <c>SDL_PROP_WINDOW_VIVANTE_SURFACE_POINTER</c>: the EGLSurface associated with
        ///     the window
        ///   </para>
        ///   <para>
        ///     On Windows:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_WINDOW_WIN32_HWND_POINTER</c>: the HWND associated with the window
        ///     - <c>SDL_PROP_WINDOW_WIN32_HDC_POINTER</c>: the HDC associated with the window
        ///     - <c>SDL_PROP_WINDOW_WIN32_INSTANCE_POINTER</c>: the HINSTANCE associated with
        ///     the window
        ///   </para>
        ///   <para>
        ///     On Wayland:
        ///   </para>
        ///   <para>
        ///     Note: The <c>xdg_*</c> window objects do not internally persist across window
        ///     show/hide calls. They will be null if the window is hidden and must be
        ///     queried each time it is shown.
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_WINDOW_WAYLAND_DISPLAY_POINTER</c>: the wl_display associated with
        ///     the window
        ///     - <c>SDL_PROP_WINDOW_WAYLAND_SURFACE_POINTER</c>: the wl_surface associated with
        ///     the window
        ///     - <c>SDL_PROP_WINDOW_WAYLAND_VIEWPORT_POINTER</c>: the wp_viewport associated
        ///     with the window
        ///     - <c>SDL_PROP_WINDOW_WAYLAND_EGL_WINDOW_POINTER</c>: the wl_egl_window
        ///     associated with the window
        ///     - <c>SDL_PROP_WINDOW_WAYLAND_XDG_SURFACE_POINTER</c>: the xdg_surface associated
        ///     with the window
        ///     - <c>SDL_PROP_WINDOW_WAYLAND_XDG_TOPLEVEL_POINTER</c>: the xdg_toplevel role
        ///     associated with the window
        ///     - 'SDL_PROP_WINDOW_WAYLAND_XDG_TOPLEVEL_EXPORT_HANDLE_STRING': the export
        ///     handle associated with the window
        ///     - <c>SDL_PROP_WINDOW_WAYLAND_XDG_POPUP_POINTER</c>: the xdg_popup role
        ///     associated with the window
        ///     - <c>SDL_PROP_WINDOW_WAYLAND_XDG_POSITIONER_POINTER</c>: the xdg_positioner
        ///     associated with the window, in popup mode
        ///   </para>
        ///   <para>
        ///     On X11:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_WINDOW_X11_DISPLAY_POINTER</c>: the X11 Display associated with
        ///     the window
        ///     - <c>SDL_PROP_WINDOW_X11_SCREEN_NUMBER</c>: the screen number associated with
        ///     the window
        ///     - <c>SDL_PROP_WINDOW_X11_WINDOW_NUMBER</c>: the X11 Window associated with the
