        ///     - <c>SDL_PROP_WINDOW_EMSCRIPTEN_KEYBOARD_ELEMENT_STRING</c>: the keyboard
        ///     element that associates keyboard events to this window
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        public uint GetProperties() => Sdl.Video.GetWindowProperties(this);

