        /// <since>
        ///   This function is available since SDL 3.4.0.
        /// </since>
        public bool SetProgressValue(float value) => Sdl.Video.SetWindowProgressValue(this, value);

        /// <summary>
        ///   Set relative mouse mode for a window.
        /// </summary>
        /// <param name="enabled">true to enable relative mode, false to disable.</param>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     While the window has focus and relative mouse mode is enabled, the cursor
        ///     is hidden, the mouse position is constrained to the window, and SDL will
        ///     report continuous relative mouse motion even if the mouse is at the edge of
        ///     the window.
        ///   </para>
        ///   <para>
        ///     If you'd like to keep the mouse position fixed while in relative mode you
        ///     can use SDL_SetWindowMouseRect(). If you'd like the cursor to be at a
        ///     specific location when relative mode ends, you should use
        ///     SDL_WarpMouseInWindow() before disabling relative mode.
        ///   </para>
        ///   <para>
        ///     This function will flush any pending mouse motion for this window.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetWindowRelativeMouseMode"/>
        public bool SetRelativeMouseMode(bool enabled) => Sdl.Mouse.SetWindowRelativeMouseMode(this, enabled);

        /// <summary>
        ///   Set the user-resizable state of a window.
        /// </summary>
        /// <param name="resizable">true to allow resizing, false to disallow.</param>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     This will add or remove the window's <c>SDL_WINDOW_RESIZABLE</c> flag and
        ///     allow/disallow user resizing of the window. This is a no-op if the window's
        ///     resizable state already matches the requested state.
        ///   </para>
        ///   <para>
        ///     You can't change the resizable state of a fullscreen window.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetWindowFlags"/>
        public bool SetResizable(bool resizable) => Sdl.Video.SetWindowResizable(this, resizable);

        /// <summary>
        ///   Set the shape of a transparent window.
        /// </summary>
        /// <param name="shape">
        ///   the surface representing the shape of the window, or NULL to
        ///   remove any current shape.
        /// </param>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     This sets the alpha channel of a transparent window and any fully
        ///     transparent areas are also transparent to mouse clicks. If you are using
        ///     something besides the SDL render API, then you are responsible for drawing
        ///     the alpha channel of the window to match the shape alpha channel to get
        ///     consistent cross-platform results.
        ///   </para>
        ///   <para>
        ///     The shape is copied inside this function, so you can free it afterwards. If
        ///     your shape surface changes, you should call SDL_SetWindowShape() again to
        ///     update the window. This is an expensive operation, so should be done
        ///     sparingly.
        ///   </para>
        ///   <para>
        ///     The window must have been created with the SDL_WINDOW_TRANSPARENT flag.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        public bool SetShape(SdlSurface* shape) => Sdl.Video.SetWindowShape(this, shape);

        /// <summary>
        ///   Request that the size of a window's client area be set.
        /// </summary>
        /// <param name="w">the width of the window, must be &gt; 0.</param>
        /// <param name="h">the height of the window, must be &gt; 0.</param>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     If the window is in a fullscreen or maximized state, this request has no
        ///     effect.
        ///   </para>
        ///   <para>
        ///     To change the exclusive fullscreen mode of a window, use
        ///     SDL_SetWindowFullscreenMode().
        ///   </para>
        ///   <para>
        ///     On some windowing systems, this request is asynchronous and the new window
        ///     size may not have have been applied immediately upon the return of this
        ///     function. If an immediate change is required, call SDL_SyncWindow() to
        ///     block until the changes have taken effect.
        ///   </para>
        ///   <para>
        ///     When the window size changes, an SDL_EVENT_WINDOW_RESIZED event will be
        ///     emitted with the new window dimensions. Note that the new dimensions may
        ///     not match the exact size requested, as some windowing systems can restrict
        ///     the window size in certain scenarios (e.g. constraining the size of the
        ///     content area to remain within the usable desktop bounds). Additionally, as
        ///     this is just a request, it can be denied by the windowing system.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetWindowSize"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.SetWindowFullscreenMode"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.SyncWindow"/>
        public bool SetSize(int w, int h) => Sdl.Video.SetWindowSize(this, w, h);

        /// <summary>
        ///   Toggle VSync for the window surface.
        /// </summary>
        /// <param name="vsync">the vertical refresh sync interval.</param>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     When a window surface is created, vsync defaults to
        ///     SDL_WINDOW_SURFACE_VSYNC_DISABLED.
        ///   </para>
        ///   <para>
        ///     The <c>vsync</c> parameter can be 1 to synchronize present with every vertical
        ///     refresh, 2 to synchronize present with every second vertical refresh, etc.,
        ///     SDL_WINDOW_SURFACE_VSYNC_ADAPTIVE for late swap tearing (adaptive vsync),
        ///     or SDL_WINDOW_SURFACE_VSYNC_DISABLED to disable. Not every value is
        ///     supported by every driver, so you should check the return value to see
        ///     whether the requested setting is supported.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetWindowSurfaceVSync"/>
        public bool SetSurfaceVSync(int vsync) => Sdl.Video.SetWindowSurfaceVSync(this, vsync);

        /// <summary>
        ///   Set the title of a window.
        /// </summary>
        /// <param name="title">the desired window title in UTF-8 format.</param>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     This string is expected to be in UTF-8 encoding.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetWindowTitle"/>
        public bool SetTitle(string title) => Sdl.Video.SetWindowTitle(this, title);

        /// <summary>
        ///   Show a window.
        /// </summary>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.HideWindow"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.RaiseWindow"/>
        public bool Show() => Sdl.Video.ShowWindow(this);

        /// <summary>
        ///   Display the system-level window menu.
        /// </summary>
        /// <param name="x">
        ///   the x coordinate of the menu, relative to the origin (top-left) of
        ///   the client area.
        /// </param>
        /// <param name="y">
        ///   the y coordinate of the menu, relative to the origin (top-left) of
        ///   the client area.
        /// </param>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     This default window menu is provided by the system and on some platforms
        ///     provides functionality for setting or changing privileged state on the
        ///     window, such as moving it between workspaces or displays, or toggling the
        ///     always-on-top property.
        ///   </para>
        ///   <para>
        ///     On platforms or desktops where this is unsupported, this function does
        ///     nothing.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        public bool ShowSystemMenu(int x, int y) => Sdl.Video.ShowWindowSystemMenu(this, x, y);

        /// <summary>
        ///   Start accepting Unicode text input events in a window.
        /// </summary>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     This function will enable text input (SDL_EVENT_TEXT_INPUT and
        ///     SDL_EVENT_TEXT_EDITING events) in the specified window. Please use this
        ///     function paired with SDL_StopTextInput().
        ///   </para>
        ///   <para>
        ///     Text input events are not received by default.
        ///   </para>
        ///   <para>
        ///     On some platforms using this function shows the screen keyboard and/or
        ///     activates an IME, which can prevent some key press events from being passed
        ///     through.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.SetTextInputArea"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.StartTextInputWithProperties"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.StopTextInput"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.TextInputActive"/>
        public bool StartTextInput() => Sdl.Keyboard.StartTextInput(this);

        /// <summary>
        ///   Start accepting Unicode text input events in a window, with properties
        ///   describing the input.
        /// </summary>
        /// <param name="props">the properties to use.</param>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     This function will enable text input (SDL_EVENT_TEXT_INPUT and
        ///     SDL_EVENT_TEXT_EDITING events) in the specified window. Please use this
        ///     function paired with SDL_StopTextInput().
        ///   </para>
        ///   <para>
        ///     Text input events are not received by default.
        ///   </para>
        ///   <para>
        ///     On some platforms using this function shows the screen keyboard and/or
        ///     activates an IME, which can prevent some key press events from being passed
        ///     through.
        ///   </para>
        ///   <para>
        ///     These are the supported properties:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_TEXTINPUT_TYPE_NUMBER</c> - an SDL_TextInputType value that
        ///     describes text being input, defaults to SDL_TEXTINPUT_TYPE_TEXT.
        ///     - <c>SDL_PROP_TEXTINPUT_CAPITALIZATION_NUMBER</c> - an SDL_Capitalization value
        ///     that describes how text should be capitalized, defaults to
        ///     SDL_CAPITALIZE_SENTENCES for normal text entry, SDL_CAPITALIZE_WORDS for
        ///     SDL_TEXTINPUT_TYPE_TEXT_NAME, and SDL_CAPITALIZE_NONE for e-mail
        ///     addresses, usernames, and passwords.
        ///     - <c>SDL_PROP_TEXTINPUT_AUTOCORRECT_BOOLEAN</c> - true to enable auto completion
        ///     and auto correction, defaults to true.
        ///     - <c>SDL_PROP_TEXTINPUT_MULTILINE_BOOLEAN</c> - true if multiple lines of text
        ///     are allowed. This defaults to true if SDL_HINT_RETURN_KEY_HIDES_IME is
        ///     "0" or is not set, and defaults to false if SDL_HINT_RETURN_KEY_HIDES_IME
        ///     is "1".
        ///   </para>
        ///   <para>
        ///     On Android you can directly specify the input type:
        ///   </para>
        ///   <para>
        ///     - <c>SDL_PROP_TEXTINPUT_ANDROID_INPUTTYPE_NUMBER</c> - the text input type to
        ///     use, overriding other properties. This is documented at
        ///     https://developer.android.com/reference/android/text/InputType
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.SetTextInputArea"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.StartTextInput"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.StopTextInput"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.TextInputActive"/>
        public bool StartTextInputWithProperties(uint props) => Sdl.Keyboard.StartTextInputWithProperties(this, props);

        /// <summary>
        ///   Stop receiving any text input events in a window.
