        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     If SDL_StartTextInput() showed the screen keyboard, this function will hide
        ///     it.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.StartTextInput"/>
        public bool StopTextInput() => Sdl.Keyboard.StopTextInput(this);

        /// <summary>
        ///   Block until any pending window state is finalized.
        /// </summary>
        /// <returns>
        ///   true on success or false if the operation timed out before the
        ///   window was in the requested state.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     On asynchronous windowing systems, this acts as a synchronization barrier
        ///     for pending window state. It will attempt to wait until any pending window
        ///     state has been applied and is guaranteed to return within finite time. Note
        ///     that for how long it can potentially block depends on the underlying window
        ///     system, as window state changes may involve somewhat lengthy animations
        ///     that must complete before the window is in its final requested state.
        ///   </para>
        ///   <para>
        ///     On windowing systems where changes are immediate, this does nothing.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.SetWindowSize"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.SetWindowPosition"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.SetWindowFullscreen"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.MinimizeWindow"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.MaximizeWindow"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.RestoreWindow"/>
        public bool Sync() => Sdl.Video.SyncWindow(this);

        /// <summary>
        ///   Check whether or not Unicode text input events are enabled for a window.
        /// </summary>
        /// <returns>true if text input events are enabled else false.</returns>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.StartTextInput"/>
        public bool TextInputActive() => Sdl.Keyboard.TextInputActive(this);

        /// <summary>
        ///   Copy the window surface to the screen.
        /// </summary>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     This is the function you use to reflect any changes to the surface on the
        ///     screen.
        ///   </para>
        ///   <para>
        ///     This function is equivalent to the SDL 1.2 API SDL_Flip().
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetWindowSurface"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.UpdateWindowSurfaceRects"/>
        public bool UpdateSurface() => Sdl.Video.UpdateWindowSurface(this);

        /// <summary>
        ///   Copy areas of the window surface to the screen.
        /// </summary>
        /// <param name="rects">
        ///   an array of SDL_Rect structures representing areas of the
        ///   surface to copy, in pixels.
        /// </param>
        /// <param name="numrects">the number of rectangles.</param>
        /// <returns>
        ///   true on success or false on failure; call SDL_GetError() for more
        ///   information.
        /// </returns>
        /// <remarks>
        ///   <para>
        ///     This is the function you use to reflect changes to portions of the surface
        ///     on the screen.
        ///   </para>
        ///   <para>
        ///     This function is equivalent to the SDL 1.2 API SDL_UpdateRects().
        ///   </para>
        ///   <para>
        ///     Note that this function will update <em>at least</em> the rectangles specified,
        ///     but this is only intended as an optimization; in practice, this might
        ///     update more of the screen (or all of the screen!), depending on what method
        ///     SDL uses to send pixels to the system.
        ///   </para>
        /// </remarks>
        /// <threadsafety>
        ///   This function should only be called on the main thread.
        /// </threadsafety>
        /// <since>
        ///   This function is available since SDL 3.2.0.
        /// </since>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GetWindowSurface"/>
        /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.UpdateWindowSurface"/>
        public bool UpdateSurfaceRects(SdlRect* rects, int numrects) =>
            Sdl.Video.UpdateWindowSurfaceRects(this, rects, numrects);

        /// <summary>
